# VLC (Qt5) resource path -> Fluent System Icon (regular style, like the
# bar's icon set; assets/fluent-icons/map.json uses the same names where the
# two overlap). The SVGs are in vlc/fluent/; vlc/make-icons recolours them
# with the theme. A colour key after the name picks the theme colour
# (default foreground).

# Transport
/toolbar/play_b.svg                    play
/menu/play.svg                         play
/toolbar/pause_b.svg                   pause
/toolbar/stop_b.svg                    stop
/toolbar/previous_b.svg                previous
/toolbar/next_b.svg                    next
/toolbar/faster.svg                    fast_forward
/toolbar/slower.svg                    rewind
/toolbar/faster2.svg                   fast_forward
/toolbar/slower2.svg                   rewind
/toolbar/skip_fw.svg                   skip_forward_10
/toolbar/skip_back.svg                 skip_back_10
/toolbar/frame.svg                     next_frame
/toolbar/reverse.svg                   arrow_swap
/toolbar/record.svg                    record          red
/toolbar/snapshot.svg                  camera
/toolbar/atob.svg                      arrow_bidirectional_left_right
/toolbar/atob_noa.svg                  arrow_bidirectional_left_right
/toolbar/atob_nob.svg                  arrow_bidirectional_left_right
/toolbar/eject.svg                     arrow_eject

